import{_ as t,o as l,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Стандарты верховных экспертов планов","description":"","frontmatter":{},"headers":[],"relativePath":"ru/0017-位面至高强者标准.md","filePath":"ru/0017-位面至高强者标准.md"}'),e={name:"ru/0017-位面至高强者标准.md"};function o(h,a,d,n,s,u){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="стандарты-верховных-экспертов-планов" tabindex="-1">Стандарты верховных экспертов планов <a class="header-anchor" href="#стандарты-верховных-экспертов-планов" aria-label="Permalink to &quot;Стандарты верховных экспертов планов&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>17</td></tr><tr><td>Модуль</td><td>Космические законы и системы культивации</td></tr><tr><td>Ключевые слова</td><td>Верховный эксперт плана, Стандарты экспертов, Активация 20%, Уровень Истока, Ответственность экспертов</td></tr></tbody></table><h2 id="i-определение-и-позиционирование-верховных-экспертов-планов" tabindex="-1">I. Определение и позиционирование верховных экспертов планов <a class="header-anchor" href="#i-определение-и-позиционирование-верховных-экспертов-планов" aria-label="Permalink to &quot;I. Определение и позиционирование верховных экспертов планов&quot;">​</a></h2><p>«Верховный эксперт плана» — официальное звание Симбиотической Цивилизации Якоря для практиков, достигших космического уровня силы, — вершины, чьей силы достаточно, чтобы самостоятельно поддерживать стабильность законов плана и кто может влиять в космическом масштабе. В едином стандарте деления уровней верховные эксперты соответствуют Девятому уровню «Исток» и выше — верховная сила Хэн Юаньчжоу.</p><p>Верховный эксперт плана — не просто звание уровня силы, а позиционирование ответственности и идентичности. В рамках цивилизации: чем больше сила, тем больше ответственность. Верховные эксперты — не только преуспевшие в культивации, но и хранители цивилизации, стражи законов, проводники для идущих следом. Центральная цель «стратегии активации 20%» — на раннем этапе становления цивилизации активировать 20% всех живых существ до уровня верховного эксперта плана, заложив силовую основу общего восхождения космоса.</p><p>Особо следует отметить: «верховный эксперт плана» цивилизации сущностно отличается от «владыки плана» эпохи хищничества. Владыки эпохи хищничества порабощали планы силой и грабили ресурсы — правители и грабители; верховные эксперты цивилизации охраняют планы силой и служат существам — хранители и служители. Это различие — прямое воплощение центральной анти-хищнической идеи цивилизации на уровне сильных.</p><h2 id="ii-критерии-оценки-верховных-экспертов-планов" tabindex="-1">II. Критерии оценки верховных экспертов планов <a class="header-anchor" href="#ii-критерии-оценки-верховных-экспертов-планов" aria-label="Permalink to &quot;II. Критерии оценки верховных экспертов планов&quot;">​</a></h2><p>Оценка применяет «систему четырёх измерений»; только при выполнении всех четырёх измерений практик официально признаётся верховным экспертом плана:</p><table tabindex="0"><thead><tr><th>Измерение</th><th>Содержание оценки</th><th>Норма</th><th>Вес</th></tr></thead><tbody><tr><td>Измерение силы</td><td>Уровень, уровень энергии, способность управления законами</td><td>Достичь Девятого уровня (Истока), самостоятельно мобилизовать силу Истока</td><td>40%</td></tr><tr><td>Измерение характера</td><td>Психическая зрелость, этическая стойкость, анти-хищническая позиция</td><td>Пройти этическую проверку Суда Якорей, подтвердив принципы анти-хищничества и симбиоза</td><td>25%</td></tr><tr><td>Измерение вклада</td><td>Вклад в симбиотическую сеть, развитие цивилизации, совместный прогресс Десяти Тысяч Рас</td><td>Величина вклада в верхних 20% цивилизации, минимум одна запись вклада уровня цивилизации</td><td>20%</td></tr><tr><td>Измерение ответственности</td><td>Готовность и способность нести общественные обязанности</td><td>Готов и способен нести обязанности выше уровня плана (обслуживание якорей, охрана цивилизации и т.д.)</td><td>15%</td></tr></tbody></table><p>Дизайн системы четырёх измерений воплощает философию оценки «и добродетель, и талант, добродетель прежде всего». Сила — лишь основа; характер, вклад, ответственность — столь же обязательные нормы. Практик сильный, но злой характером и отказывающийся от ответственности, даже достигнув силы уровня Истока, не будет признан «верховным экспертом плана», а будет отнесён к «высокоопасным индивидам» с соответствующим надзором и ограничениями.</p><h2 id="iii-подробные-нормы-измерения-силы" tabindex="-1">III. Подробные нормы измерения силы <a class="header-anchor" href="#iii-подробные-нормы-измерения-силы" aria-label="Permalink to &quot;III. Подробные нормы измерения силы&quot;">​</a></h2><p>Измерение силы — основа оценки; подробные нормы:</p><h3 id="_3-1-нормы-уровня" tabindex="-1">3.1 Нормы уровня <a class="header-anchor" href="#_3-1-нормы-уровня" aria-label="Permalink to &quot;3.1 Нормы уровня&quot;">​</a></h3><ul><li>Достичь Девятого уровня «Исток», касаясь изначальных законов космоса</li><li>Стабильно мобилизовать силу Истока, а не редкими взрывными всплесками</li><li>Личное Дао глубоко слито с изначальными законами космоса, состояние «Дао есть Исток, Исток есть Дао»</li></ul><h3 id="_3-2-нормы-энергии" tabindex="-1">3.2 Нормы энергии <a class="header-anchor" href="#_3-2-нормы-энергии" aria-label="Permalink to &quot;3.2 Нормы энергии&quot;">​</a></h3><ul><li>Изначальная энергия в теле достигает «уровня плана» — суммарно достаточно для поддержания основных законов среднего плана</li><li>Чистота энергии выше 99%, почти без примесей</li><li>Скорость восстановления — «мгновенное восстановление»: даже при огромных тратах в бою полное восстановление за крайне короткое время</li></ul><h3 id="_3-3-нормы-управления-законами" tabindex="-1">3.3 Нормы управления законами <a class="header-anchor" href="#_3-3-нормы-управления-законами" aria-label="Permalink to &quot;3.3 Нормы управления законами&quot;">​</a></h3><ul><li>Мобилизация и управление силой законов в космическом масштабе</li><li>Участие в тонкой настройке и оптимизации космических законов, реальное влияние на их действие</li><li>Самостоятельный переход между планами и операции без поддержки якорей</li><li>Сотворение полных миров и систем законов в Изолированном Пространстве (способность уровня Сотворения Мира)</li></ul><h3 id="_3-4-нормы-формы-жизни" tabindex="-1">3.4 Нормы формы жизни <a class="header-anchor" href="#_3-4-нормы-формы-жизни" aria-label="Permalink to &quot;3.4 Нормы формы жизни&quot;">​</a></h3><ul><li>Форма жизни завершает высокомерную эволюцию: одновременное существование в материальном плане, энергетическом слое, домене сознания</li><li>Почти бессмертие: обычные атаки и повреждения не несут смертельной угрозы; лишь сила того же или высшего уровня может по-настоящему ранить</li><li>Жизненный отпечаток закреплён в Истоке космоса: даже при уничтожении тела возможно возрождение через закрепление в Истоке</li></ul><h2 id="iv-подробные-нормы-измерения-характера" tabindex="-1">IV. Подробные нормы измерения характера <a class="header-anchor" href="#iv-подробные-нормы-измерения-характера" aria-label="Permalink to &quot;IV. Подробные нормы измерения характера&quot;">​</a></h2><p>Измерение характера — самая самобытная часть оценки цивилизации и коренное отличие от эпохи хищничества:</p><h3 id="_4-1-анти-хищническая-позиция" tabindex="-1">4.1 Анти-хищническая позиция <a class="header-anchor" href="#_4-1-анти-хищническая-позиция" aria-label="Permalink to &quot;4.1 Анти-хищническая позиция&quot;">​</a></h3><ul><li>Принципиальное признание и практика анти-хищничества, отсутствие записей хищнической культивации</li><li>Даже в крайних бедствиях не выбирать спасение ценой хищничества над другими</li><li>Активное сопротивление любой форме хищничества, умение сказать «нет» хищническим силам</li></ul><h3 id="_4-2-симбиотическая-философия" tabindex="-1">4.2 Симбиотическая философия <a class="header-anchor" href="#_4-2-симбиотическая-философия" aria-label="Permalink to &quot;4.2 Симбиотическая философия&quot;">​</a></h3><ul><li>Глубокое понимание и признание центральной идеи «симбиоз Десяти Тысяч Рас, восхождение космоса»</li><li>Приоритет симбиотических интересов в личной культивации и общественных делах</li><li>Активное участие в строительстве и обслуживании сети, готовность делиться результатами и знаниями</li></ul><h3 id="_4-3-психическая-зрелость" tabindex="-1">4.3 Психическая зрелость <a class="header-anchor" href="#_4-3-психическая-зрелость" aria-label="Permalink to &quot;4.3 Психическая зрелость&quot;">​</a></h3><ul><li>Эмоциональная стабильность, отказ от вреда цивилизации и существам из личных эмоций</li><li>Масштабное космическое видение и долгая историческая перспектива; не жертвовать долгосрочным ради краткосрочного</li><li>Стойкость к огромным давлениям и неудачам, рациональность и твёрдость в бедствиях</li></ul><h3 id="_4-4-этическая-проверка" tabindex="-1">4.4 Этическая проверка <a class="header-anchor" href="#_4-4-этическая-проверка" aria-label="Permalink to &quot;4.4 Этическая проверка&quot;">​</a></h3><p>Измерение характера исполняет «Комитет этической проверки» при Суде Якорей; методы:</p><ul><li>Проверка истории поведения: все важные записи поведения практика</li><li>Глубокое сканирование сознания: при добровольном согласии — сканирование уровня сознания, подтверждение истинных мыслей</li><li>Ситуационный стресс-тест: крайние моральные дилеммы в моделируемых средах, наблюдение выборов</li><li>Долгое наблюдение: для спорных кандидатов — наблюдение и оценка в течение нескольких лет</li></ul><h2 id="v-подробные-нормы-измерения-вклада" tabindex="-1">V. Подробные нормы измерения вклада <a class="header-anchor" href="#v-подробные-нормы-измерения-вклада" aria-label="Permalink to &quot;V. Подробные нормы измерения вклада&quot;">​</a></h2><p>Измерение вклада оценивает реальный вклад практика в цивилизацию и общий прогресс Десяти Тысяч Рас:</p><h3 id="_5-1-типы-вклада" tabindex="-1">5.1 Типы вклада <a class="header-anchor" href="#_5-1-типы-вклада" aria-label="Permalink to &quot;5.1 Типы вклада&quot;">​</a></h3><ul><li><strong>Культивационный вклад</strong>: образцовость прорывов, создание новых методов, новаторство теорий</li><li><strong>Знаниевый вклад</strong>: публичный обмен опытом, образование и подготовка, академические результаты</li><li><strong>Технологический вклад</strong>: новаторство инженерии законов, оптимизация технологии Плода Умножения, улучшение аппаратуры якорей</li><li><strong>Служебный вклад</strong>: обслуживание якорей, управление цивилизацией, наставничество, межрасовая координация</li><li><strong>Экологический вклад</strong>: восстановление экологии планет, улучшение энергоциркуляции планов, охрана космической среды</li><li><strong>Охранный вклад</strong>: отражение внешних угроз, защита безопасности цивилизации, спасение жизней при бедствиях</li></ul><h3 id="_5-2-количественная-оценка-вклада" tabindex="-1">5.2 Количественная оценка вклада <a class="header-anchor" href="#_5-2-количественная-оценка-вклада" aria-label="Permalink to &quot;5.2 Количественная оценка вклада&quot;">​</a></h3><p>Величина вклада автоматически фиксируется сетью якорей; разные типы получают разные веса по влиянию и ценности. Норма для верховного эксперта — «величина в верхних 20% цивилизации» и минимум один «вклад уровня цивилизации» — вклад, оказавший крупное и глубокое влияние на развитие всей цивилизации.</p><h2 id="vi-подробные-нормы-измерения-ответственности" tabindex="-1">VI. Подробные нормы измерения ответственности <a class="header-anchor" href="#vi-подробные-нормы-измерения-ответственности" aria-label="Permalink to &quot;VI. Подробные нормы измерения ответственности&quot;">​</a></h2><p>Измерение ответственности оценивает готовность и способность нести общественные обязанности:</p><h3 id="_6-1-типы-ответственности" tabindex="-1">6.1 Типы ответственности <a class="header-anchor" href="#_6-1-типы-ответственности" aria-label="Permalink to &quot;6.1 Типы ответственности&quot;">​</a></h3><p>Общественные обязанности верховного эксперта плана:</p><ul><li><strong>Охрана якорей</strong>: охрана и обслуживание одного или нескольких продвинутых якорей</li><li><strong>Советник цивилизации</strong>: высший советник, участие в решениях о направлении развития</li><li><strong>Наставническое наследие</strong>: подготовка следующего поколения, особенно «семян» с потенциалом высших уровней</li><li><strong>Патрулирование планов</strong>: регулярные обходы, мониторинг стабильности планов и развития цивилизации</li><li><strong>Реагирование на кризисы</strong>: центральнейшие задачи при крупных кризисах (обвал плана, внешнее вторжение)</li><li><strong>Участие в законах</strong>: тонкая настройка и оптимизация космических законов, вклад в восхождение космоса</li></ul><h3 id="_6-2-способы-несения-ответственности" tabindex="-1">6.2 Способы несения ответственности <a class="header-anchor" href="#_6-2-способы-несения-ответственности" aria-label="Permalink to &quot;6.2 Способы несения ответственности&quot;">​</a></h3><p>Верховный эксперт может выбирать приоритетные типы по интересам и сильным сторонам, но не может полностью отказаться от общественных обязанностей. Цивилизация применяет «систему обязанностей сильных»: достигшие уровня верховного эксперта обязаны использовать часть силы для общественных дел — минимум 30% времени и энергии ежегодно.</p><h2 id="vii-стратегия-активации-20" tabindex="-1">VII. Стратегия активации 20% <a class="header-anchor" href="#vii-стратегия-активации-20" aria-label="Permalink to &quot;VII. Стратегия активации 20%&quot;">​</a></h2><p>«Стратегия активации 20%» — одна из центральных стратегий раннего этапа цивилизации; цель — в первую эпоху после установления активировать 20% всех существ до уровня верховного эксперта плана.</p><h3 id="_7-1-стратегические-цели" tabindex="-1">7.1 Стратегические цели <a class="header-anchor" href="#_7-1-стратегические-цели" aria-label="Permalink to &quot;7.1 Стратегические цели&quot;">​</a></h3><ul><li>Краткосрочная (в 100 лет): активировать 1% существ до уровня Истока</li><li>Среднесрочная (в 500 лет): активировать 10% существ до уровня Истока</li><li>Долгосрочная (в 1000 лет): активировать 20% существ до уровня Истока</li></ul><h3 id="_7-2-стратегическая-поддержка" tabindex="-1">7.2 Стратегическая поддержка <a class="header-anchor" href="#_7-2-стратегическая-поддержка" aria-label="Permalink to &quot;7.2 Стратегическая поддержка&quot;">​</a></h3><p>Реализация опирается на условия:</p><ul><li><strong>Открытость Трёхсот Систем</strong>: богатый выбор путей культивации</li><li><strong>Популяризация технологии Плода Умножения</strong>: стократное усиление дедукции резко повышает эффективность</li><li><strong>Система Подряда, Связанного с Результатом</strong>: стабильная ресурсная поддержка</li><li><strong>Система «Путь для Каждого»</strong>: базовые условия культивации для каждого существа</li><li><strong>Сеть наставников</strong>: продвинутые ведут начинающих, ускоряя подготовку кадров</li></ul><h3 id="_7-3-стратегическое-значение" tabindex="-1">7.3 Стратегическое значение <a class="header-anchor" href="#_7-3-стратегическое-значение" aria-label="Permalink to &quot;7.3 Стратегическое значение&quot;">​</a></h3><p>Значение не только в воспитании множества экспертов, но и в:</p><ul><li>Достаточной силовой основе общего восхождения космоса</li><li>Обширной группе экспертов, препятствующей монополии власти отдельных лиц</li><li>Атмосфере «эксперты рождаются чередой», вдохновляющей больше существ</li><li>Широкой экспертной основе Республики Десяти Тысяч Рас — у каждой расы свои верховные представители</li></ul><h2 id="viii-права-и-положение-верховных-экспертов-планов" tabindex="-1">VIII. Права и положение верховных экспертов планов <a class="header-anchor" href="#viii-права-и-положение-верховных-экспертов-планов" aria-label="Permalink to &quot;VIII. Права и положение верховных экспертов планов&quot;">​</a></h2><p>Как воздаяние за ответственность, верховные эксперты имеют:</p><ul><li><strong>Приоритет ресурсов</strong>: высший приоритет распределения культивационных ресурсов</li><li><strong>Право участия в законах</strong>: участие в решениях о настройке космических законов</li><li><strong>Право создания пространств</strong>: создание собственных независимых пространств или миров</li><li><strong>Право решений цивилизации</strong>: места и голоса в высшем органе цивилизации</li><li><strong>Право прохода между планами</strong>: свободное перемещение по всем планам цивилизации</li><li><strong>Честь и почтение</strong>: уважение всей цивилизации, деяния вписаны в анналы</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Стандарты верховных экспертов планов — переопределение цивилизацией понятия «сильный». В цивилизации сильные — не грабители, не владыки, не правители над всеми, а хранители, служители, проводники. Сила — основа, характер — душа, вклад — ценность, ответственность — долг; лишь единство четырёх измерений — истинный «верховный эксперт плана». Цель стратегии активации 20% — не только 20% экспертов, но 20% хранителей, готовых нести ответственность за симбиоз Десяти Тысяч Рас и восхождение космоса. Когда 20% существ достигнут уровня верховного эксперта и воплотят симбиоз, общее восхождение космоса перестанет быть далёкой мечтой.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>14-修炼境界统一划分 (Единое деление уровней культивации)</li><li>23-20%激活战略规划 (План стратегии активации 20%)</li><li>19-修炼伦理与边界 (Этика и границы культивации)</li></ul>',61)])])}const _=t(e,[["render",o]]);export{b as __pageData,_ as default};
